UPDATE instance_delete_operations SET
  instance_id = #{instanceId}, instance_name = #{instanceName}, container_name = #{containerName},
  force_delete = #{force}, status = #{status}, stage = #{stage}, wechat_account_count = #{wechatAccountCount},
  miniapp_binding_count = #{miniappBindingCount}, cleanup_operation_ids_json = #{cleanupOperationIdsJson},
  last_error = #{lastError}, updated_at = #{updatedAt}, completed_at = #{completedAt}
WHERE operation_id = #{operationId}
